const hasAnyTenant = `-- name: HasAnyTenant :one
SELECT EXISTS (SELECT 1 FROM tenants)
`

func (q *Queries) HasAnyTenant(ctx context.Context) (bool, error) {
	row := q.db.QueryRow(ctx, hasAnyTenant)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const hasAnyUser = `-- name: HasAnyUser :one
SELECT EXISTS (SELECT 1 FROM users WHERE tenant_id = $1) AS has_users
`

// EXISTS stops at the first row: O(1) regardless of table size, unlike count(*).
func (q *Queries) HasAnyUser(ctx context.Context, tenantID int64) (bool, error) {
	row := q.db.QueryRow(ctx, hasAnyUser, tenantID)
	var has_users bool
	err := row.Scan(&has_users)
	return has_users, err
}

const isTenantDomain = `-- name: IsTenantDomain :one
SELECT EXISTS (
    SELECT 1 FROM tenant_domains
    WHERE domain = lower($1::text)
      AND tenant_id = $2::bigint
) AS owned
`

type IsTenantDomainParams struct {
	Domain   string
	TenantID int64
}

// Whether an address belongs to this company. Invitations are refused for
// anything else: an address on a domain the company does not own could not be
// read by the company, so a link sent there proves nothing about employment.
func (q *Queries) IsTenantDomain(ctx context.Context, arg IsTenantDomainParams) (bool, error) {
	row := q.db.QueryRow(ctx, isTenantDomain, arg.Domain, arg.TenantID)
	var owned bool
	err := row.Scan(&owned)
	return owned, err
}

const listDepartments = `-- name: ListDepartments :many
SELECT id, tenant_id, code, name, parent_id, path, level, sort_order, status, created_at, updated_at FROM departments WHERE tenant_id = $1 ORDER BY path, sort_order, id
`

func (q *Queries) ListDepartments(ctx context.Context, tenantID int64) ([]Department, error) {
	rows, err := q.db.Query(ctx, listDepartments, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Department
	for rows.Next() {
		var i Department
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Code,
			&i.Name,
			&i.ParentID,
			&i.Path,
			&i.Level,
			&i.SortOrder,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

