const upsertUserPassword = `-- name: UpsertUserPassword :exec
INSERT INTO users (tenant_id, employee_id, username, password_hash)
VALUES (
    $1::bigint,
    $2::bigint,
    $3::text,
    $4::text
)
ON CONFLICT (employee_id) DO UPDATE
SET password_hash = EXCLUDED.password_hash,
    status        = 'ACTIVE',
    failed_count  = 0,
    updated_at    = now()
`

type UpsertUserPasswordParams struct {
	TenantID     int64
	EmployeeID   int64
	Username     string
	PasswordHash string
}

// Activation is the same operation whether or not an account already exists —
// an employee imported with a login gets their password replaced, one imported
// without gets a row. employee_id is UNIQUE, so the conflict target is exact.
func (q *Queries) UpsertUserPassword(ctx context.Context, arg UpsertUserPasswordParams) error {
	_, err := q.db.Exec(ctx, upsertUserPassword,
		arg.TenantID,
		arg.EmployeeID,
		arg.Username,
		arg.PasswordHash,
	)
	return err
}

const widestDataScope = `-- name: WidestDataScope :one
SELECT s.scope_type, s.custom_dept_ids
FROM role_data_scopes s
JOIN employee_roles er ON er.role_id = s.role_id AND er.tenant_id = s.tenant_id
WHERE s.tenant_id = $1 AND er.employee_id = $2 AND s.module = $3
ORDER BY CASE s.scope_type
           WHEN 'ALL' THEN 4
           WHEN 'CUSTOM' THEN 3
           WHEN 'DEPT_AND_SUB' THEN 2
           WHEN 'DEPT' THEN 1
           ELSE 0
         END DESC
LIMIT 1
`

type WidestDataScopeParams struct {
	TenantID   int64
	EmployeeID int64
	Module     string
}

type WidestDataScopeRow struct {
	ScopeType     string
	CustomDeptIds []int64
}

// Someone with several roles gets the widest of them: adding a role must
// never take visibility away. Ordered by how much each scope reveals.
func (q *Queries) WidestDataScope(ctx context.Context, arg WidestDataScopeParams) (WidestDataScopeRow, error) {
	row := q.db.QueryRow(ctx, widestDataScope, arg.TenantID, arg.EmployeeID, arg.Module)
	var i WidestDataScopeRow
	err := row.Scan(&i.ScopeType, &i.CustomDeptIds)
	return i, err
}
